package warehouse_warehouse_service.support;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Runtime helpers implementing the Datrix {@code Geo} builtin category.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
public final class GeoHelpers {

  private static final double EARTH_RADIUS_NM = 3440.065;
  private static final double EARTH_RADIUS_KM = 6371.0;

  private GeoHelpers() {}

  /** Great-circle distance in nautical miles between two WGS84 points. */
  public static double distanceNm(double lat1, double lng1, double lat2, double lng2) {
    return EARTH_RADIUS_NM * centralAngle(lat1, lng1, lat2, lng2);
  }

  /** Great-circle distance in kilometres between two WGS84 points. */
  public static double distanceKm(double lat1, double lng1, double lat2, double lng2) {
    return EARTH_RADIUS_KM * centralAngle(lat1, lng1, lat2, lng2);
  }

  private static double centralAngle(double lat1, double lng1, double lat2, double lng2) {
    double phi1 = Math.toRadians(lat1);
    double phi2 = Math.toRadians(lat2);
    double dPhi = Math.toRadians(lat2 - lat1);
    double dLambda = Math.toRadians(lng2 - lng1);
    double a =
        Math.pow(Math.sin(dPhi / 2), 2)
            + Math.cos(phi1) * Math.cos(phi2) * Math.pow(Math.sin(dLambda / 2), 2);
    return 2 * Math.atan2(Math.sqrt(a), Math.sqrt(Math.max(0.0, 1.0 - a)));
  }

  /**
   * Convert parsed geospatial feature maps to GeoJSON Feature objects. Each input map must have
   * {@code latitude}/{@code longitude} (or {@code lat}/{@code lng}) keys. {@code featureType} is
   * stored in {@code properties.featureType}.
   */
  public static List<Map<String, Object>> toGeoJson(
      List<Map<String, Object>> features, String featureType) {
    List<Map<String, Object>> result = new ArrayList<>();
    for (Map<String, Object> feat : features) {
      Object lat = feat.containsKey("latitude") ? feat.get("latitude") : feat.get("lat");
      Object lng = feat.containsKey("longitude") ? feat.get("longitude") : feat.get("lng");
      if (lat == null || lng == null) {
        continue;
      }
      Map<String, Object> properties = new LinkedHashMap<>();
      properties.put("featureType", featureType);
      for (Map.Entry<String, Object> entry : feat.entrySet()) {
        String key = entry.getKey();
        if (!key.equals("latitude")
            && !key.equals("longitude")
            && !key.equals("lat")
            && !key.equals("lng")) {
          properties.put(key, entry.getValue());
        }
      }
      Map<String, Object> geometry = new LinkedHashMap<>();
      geometry.put("type", "Point");
      geometry.put(
          "coordinates", List.of(((Number) lng).doubleValue(), ((Number) lat).doubleValue()));

      Map<String, Object> geoJsonFeature = new LinkedHashMap<>();
      geoJsonFeature.put("type", "Feature");
      geoJsonFeature.put("geometry", geometry);
      geoJsonFeature.put("properties", properties);
      result.add(geoJsonFeature);
    }
    return result;
  }

  /**
   * Compute the centroid {@code [lat, lng]} of a GeoJSON geometry map ({@code type}/{@code
   * coordinates}). Supports Point, Polygon, and MultiPolygon; polygon centroids are the arithmetic
   * mean of the exterior ring, multi-polygon centroids are area-weighted (Shoelace formula as an
   * area proxy).
   */
  @SuppressWarnings("unchecked")
  public static double[] centroid(Map<String, Object> geometry) {
    String geomType = String.valueOf(geometry.get("type"));
    Object coords = geometry.get("coordinates");
    if (coords == null) {
      throw new IllegalArgumentException("GeoJSON geometry missing 'coordinates'");
    }

    if ("Point".equals(geomType)) {
      List<Number> point = (List<Number>) coords;
      return new double[] {point.get(1).doubleValue(), point.get(0).doubleValue()};
    }
    if ("Polygon".equals(geomType)) {
      List<List<Number>> ring = (List<List<Number>>) ((List<?>) coords).get(0);
      return ringCentroid(ring);
    }
    if ("MultiPolygon".equals(geomType)) {
      double totalArea = 0.0;
      double weightedLat = 0.0;
      double weightedLng = 0.0;
      for (Object polygonCoordsObj : (List<?>) coords) {
        List<List<Number>> ring = (List<List<Number>>) ((List<?>) polygonCoordsObj).get(0);
        double[] c = ringCentroid(ring);
        double area = Math.abs(ringSignedArea(ring));
        totalArea += area;
        weightedLat += c[0] * area;
        weightedLng += c[1] * area;
      }
      if (totalArea == 0.0) {
        List<List<Number>> ring = (List<List<Number>>) ((List<?>) ((List<?>) coords).get(0)).get(0);
        return ringCentroid(ring);
      }
      return new double[] {weightedLat / totalArea, weightedLng / totalArea};
    }
    throw new IllegalArgumentException(
        "Unsupported geometry type '"
            + geomType
            + "' for centroid. Expected Point, Polygon, or MultiPolygon.");
  }

  private static double[] ringCentroid(List<List<Number>> ring) {
    int n = ring.size();
    if (n == 0) {
      throw new IllegalArgumentException("Empty coordinate ring");
    }
    double totalLng = 0.0;
    double totalLat = 0.0;
    for (List<Number> pt : ring) {
      totalLng += pt.get(0).doubleValue();
      totalLat += pt.get(1).doubleValue();
    }
    return new double[] {totalLat / n, totalLng / n};
  }

  private static double ringSignedArea(List<List<Number>> ring) {
    int n = ring.size();
    double area = 0.0;
    for (int i = 0; i < n; i++) {
      int j = (i + 1) % n;
      area += ring.get(i).get(0).doubleValue() * ring.get(j).get(1).doubleValue();
      area -= ring.get(j).get(0).doubleValue() * ring.get(i).get(1).doubleValue();
    }
    return area / 2.0;
  }

  /** Convert longitude to Web Mercator (EPSG:3857) tile X coordinate at the given zoom level. */
  public static int lngToTileX(double lng, int zoom) {
    int n = 1 << zoom;
    int x = (int) ((lng + 180.0) / 360.0 * n);
    return Math.max(0, Math.min(n - 1, x));
  }

  /** Convert latitude to Web Mercator (EPSG:3857) tile Y coordinate at the given zoom level. */
  public static int latToTileY(double lat, int zoom) {
    int n = 1 << zoom;
    double latRad = Math.toRadians(lat);
    int y = (int) ((1.0 - asinh(Math.tan(latRad)) / Math.PI) / 2.0 * n);
    return Math.max(0, Math.min(n - 1, y));
  }

  /**
   * {@code java.lang.Math} has no {@code asinh} -- the standard closed form: ln(x + sqrt(x^2 + 1)).
   */
  private static double asinh(double x) {
    return Math.log(x + Math.sqrt(x * x + 1.0));
  }
}
